  1→/**
  2→ * Visibility planner (P3-3, pure part).
  3→ *
  4→ * The gate acts on one field: the asset record's `visibility`. The bridge's
  5→ * team search whitelist is A ∪ B, where A is `meta list-accessible
  6→ * (visibility='team')`; an asset set to `private` drops out of A. The four
  7→ * read paths (search, get, get-by-name, files/read) share that whitelist, so
  8→ * dropping out of A is dropping out of the consumer's reach entirely.
  9→ *
 10→ * Given decisions, the baseline visibility of each asset and what the product
 11→ * reports right now, this produces the list of writes to make:
 12→ *
 13→ *   reject   → private     the gate hides what it has judged wrong
 14→ *   admit    → baseline    as entered (team)
 15→ *   pending  → baseline    the gate does not hide what it could not judge;
 16→ *                          a pending asset stays exactly as the baseline left it
 17→ *
 18→ * `reset` ignores decisions and restores the baseline for every asset — how a
 19→ * gate-off run, and the start of every gate-on run, get the same initial pool.
 20→ *
 21→ * Nothing here talks to the service; apply.sh does, and records what it read
 22→ * back. Keeping the plan pure means it is testable without a running stack.
 23→ *
 24→ * Usage (from apply.sh):
 25→ *   node plan-visibility.mjs --mode=apply|reset --baseline=gate_baseline.json --current=current.json
 26→ */
 27→
 28→import { readFileSync } from "node:fs";
 29→
 30→export const HIDDEN = "private";
 31→
 32→/**
 33→ * @param mode      "apply" | "reset"
 34→ * @param baseline  { assets: { [asset_id]: { baseline_visibility } }, decisions: [...] }
 35→ * @param current   { [asset_id]: visibility | null }   null = could not be read
 36→ */
 37→export function planVisibility({ mode, baseline, current, hide = [] }) {
 38→  if (mode !== "apply" && mode !== "reset" && mode !== "hide") throw new Error(`mode must be apply, reset or hide, got ${mode}`);
 39→  // "hide" is leave-one-out's tool: baseline for everything, private for the
 40→  // named assets, decisions ignored. Same write path, same read-back.
 41→  const hidden = new Set(hide);
 42→  if (mode === "hide" && hidden.size === 0) throw new Error("hide mode needs at least one asset id");
 43→  for (const id of hidden) {
 44→    if (!(baseline.assets ?? {})[id]) throw new Error(`cannot hide ${id}: not in the baseline`);
 45→  }
 46→  const decisions = new Map((baseline.decisions ?? []).map((d) => [d.asset_id, d]));
 47→  const changes = [];
 48→  const unchanged = [];
 49→  const unreadable = [];
 50→  const undecided = [];
 51→
 52→  for (const [assetId, row] of Object.entries(baseline.assets ?? {})) {
 53→    const base = row.baseline_visibility;
 54→    const now = current?.[assetId] ?? null;
 55→    if (now === null) {
 56→      unreadable.push(assetId);
 57→      continue;
 58→    }
 59→    let target = base;
 60→    let because = `reset to baseline (${base})`;
 61→    if (mode === "hide") {
 62→      if (hidden.has(assetId)) { target = HIDDEN; because = `leave-one-out: hidden for this run (${HIDDEN})`; }
 63→      else because = `leave-one-out: kept at baseline (${base})`;
 64→    } else if (mode === "apply") {
 65→      const d = decisions.get(assetId);
 66→      if (!d) {
 67→        undecided.push(assetId);
 68→        because = `no decision in the baseline; kept at baseline (${base})`;
 69→      } else if (d.decision === "reject") {
 70→        target = HIDDEN;
 71→        because = `gate: reject → ${HIDDEN} (${d.reasons[0]})`;
 72→      } else if (d.decision === "admit") {
 73→        because = `gate: admit → baseline (${base})`;
 74→      } else {
 75→        because = `gate: pending → baseline (${base}); the gate does not hide what it could not judge`;
 76→      }
 77→    }
 78→    if (now === target) unchanged.push({ asset_id: assetId, visibility: now, because });
 79→    else changes.push({ asset_id: assetId, from: now, to: target, because });
 80→  }
 81→  return { mode, changes, unchanged, unreadable, undecided };
 82→}
 83→
 84→export function renderPlan(plan) {
 85→  const lines = [`# visibility plan (${plan.mode})`];
 86→  for (const c of plan.changes) lines.push(`  ${c.asset_id}: ${c.from} → ${c.to}   ${c.because}`);
 87→  for (const u of plan.unchanged) lines.push(`  ${u.asset_id}: ${u.visibility} (unchanged)   ${u.because}`);
 88→  for (const id of plan.unreadable) lines.push(`  ${id}: visibility could not be read — NOT planned`);
 89→  if (plan.changes.length === 0 && plan.unreadable.length === 0) lines.push("  nothing to change");
 90→  return lines.join("\n");
 91→}
 92→
 93→if (import.meta.url === `file://${process.argv[1]}`) {
 94→  const arg = (name) => { const a = process.argv.find((x) => x.startsWith(`--${name}=`)); return a ? a.slice(name.length + 3) : null; };
 95→  const mode = arg("mode"); const baselinePath = arg("baseline"); const currentPath = arg("current");
 96→  if (!mode || !baselinePath || !currentPath) {
 97→    console.error("usage: node plan-visibility.mjs --mode=apply|reset --baseline=F --current=F [--json]");
 98→    process.exit(2);
 99→  }
100→  const plan = planVisibility({
101→    mode,
102→    baseline: JSON.parse(readFileSync(baselinePath, "utf8")),
103→    current: JSON.parse(readFileSync(currentPath, "utf8")),
104→    hide: (arg("hide") ?? "").split(",").filter(Boolean),
105→  });
106→  console.log(process.argv.includes("--json") ? JSON.stringify(plan, null, 2) : renderPlan(plan));
107→  // An unreadable asset is a failed plan: a run whose gate state is unknown is
108→  // not comparable with anything.
109→  process.exit(plan.unreadable.length > 0 ? 1 : 0);
110→}
