 1→/**
 2→ * Regression: the exit status of a real CodeBuddy Bash result must survive into
 3→ * the operation list.
 4→ *
 5→ * The collection stage read the outcome with a lowercase `Exit code:` pattern,
 6→ * but the envelope CodeBuddy actually writes spells it `Exit Code:` — with a
 7→ * capital C, after the `Stderr:` section. Every real operation therefore
 8→ * carried `exit_code: null`, and the downstream classification of failed calls
 9→ * had nothing to classify by. The synthetic fixtures used elsewhere happen to
10→ * be built without a tail section at all, which is why the defect stayed
11→ * invisible to them: the test below feeds the envelope exactly as captured.
12→ */
13→
14→import { test } from "node:test";
15→import assert from "node:assert/strict";
16→
17→import { collectArtifacts, outcomeOf } from "./collect-artifacts.mjs";
18→
19→/** A Bash result in the shape the capture observed. */
20→const envelope = (exit, stderr = "(empty)") =>
21→  "Command: curl -sfk -X POST http://127.0.0.1:8096/skill-bridge/v3/skill/search -d '{\"query\":\"x\"}'\n"
22→  + 'Stdout: {"code":0,"data":{"items":[]}}\n'
23→  + `Stderr: ${stderr}\n`
24→  + `Exit Code: ${exit}\n`
25→  + "Signal: (none)";
26→
27→const capture = (messages) => [{
28→  event: "http.request",
29→  requestId: "req-1",
30→  timestamp: "2026-09-11T00:00:00Z",
31→  headers: { "x-conversation-id": "conv-1" },
32→  body: { json: { messages } },
33→}];
34→
35→const call = (id) => ({ role: "assistant", tool_calls: [{ id, function: { name: "Bash", arguments: "{}" } }] });
36→const result = (id, content) => ({ role: "tool", tool_call_id: id, content });
37→
38→test("a real Bash envelope reports its exit status in the operation list", () => {
39→  const [session] = collectArtifacts({
40→    captureEvents: capture([
41→      call("c1"),
42→      result("c1", envelope(0)),
43→      call("c2"),
44→      result("c2", envelope(28, "curl: (28) Operation timed out after 75000 ms")),
45→    ]),
46→  });
47→  const byCall = new Map(session.operations.map((op) => [op.call_id, op]));
48→
49→  assert.equal(byCall.get("c1").result.exit_code, 0, "a clean run must report exit 0");
50→  assert.equal(byCall.get("c2").result.exit_code, 28, "a failed run must report its code");
51→});
52→
53→test("the envelope's tail sections are not read back as stderr", () => {
54→  const ok = outcomeOf(envelope(0));
55→  assert.equal(ok.exit_code, 0);
56→  assert.equal(ok.stderr, "", "`(empty)` stderr reads back empty, without `Exit Code:`");
57→
58→  const failed = outcomeOf(envelope(7, "curl: (7) Failed to connect"));
59→  assert.equal(failed.exit_code, 7);
60→  assert.equal(failed.stderr, "curl: (7) Failed to connect", "stderr stops before `Exit Code:`");
61→});
